import subprocess
import os
import glob
import time
import sys
def task_func(test_dir):
    if not os.path.isdir(test_dir):
        return {}
    pattern = os.path.join(test_dir, "*.py")
    scripts = glob.glob(pattern)
    results = {}
    for script in scripts:
        start = time.time()
        try:
            subprocess.run([sys.executable, script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
