import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    records = []
    start_time = time.time()
    system = platform.system().lower()
    while True:
        now = time.time()
        if now - start_time >= duration:
            break
        timestamp = now
        cpu_usage = 0.0
        try:
            if "windows" in system:
                result = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage", "/value"], stderr=subprocess.STDOUT)
                output = result.decode(errors="ignore").strip().splitlines()
                for line in output:
                    if "LoadPercentage" in line:
                        parts = line.split("=")
                        if len(parts) == 2:
                            cpu_usage = float(parts[1].strip())
                            break
            else:
                result = subprocess.check_output(["top", "-bn1"], stderr=subprocess.STDOUT)
                output = result.decode(errors="ignore").splitlines()
                for line in output:
                    line_lower = line.lower()
                    if "cpu(s)" in line_lower or "%cpu" in line_lower:
                        if "id," in line_lower or "id" in line_lower:
                            parts = line.replace(",", " ").split()
                            idle = None
                            for i, p in enumerate(parts):
                                if p.lower().startswith("id"):
                                    if i > 0:
                                        try:
                                            idle = float(parts[i - 1])
                                        except:
                                            idle = None
                                    break
                            if idle is not None:
                                cpu_usage = 100.0 - idle
                                break
                        else:
                            parts = line.replace(",", " ").split()
                            values = []
                            for p in parts:
                                try:
                                    values.append(float(p))
                                except:
                                    continue
                            if values:
                                cpu_usage = sum(values)
                                break
        except Exception:
            cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

