import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        if now - start_time >= duration:
            break
        if "windows" in system:
            cmd = ['typeperf', r'\Processor(_Total)\% Processor Time', '-sc', '1']
            try:
                output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode(errors='ignore').strip().splitlines()
            except Exception:
                cpu_usage = 0.0
            else:
                value_line = None
                for line in output:
                    if line and not line.lower().startswith("timestamp") and not line.lower().startswith('"counter"'):
                        value_line = line
                if value_line is None:
                    cpu_usage = 0.0
                else:
                    parts = value_line.split(',')
                    if len(parts) >= 2:
                        raw = parts[-1].strip().strip('"')
                        try:
                            cpu_usage = float(raw)
                        except ValueError:
                            cpu_usage = 0.0
                    else:
                        cpu_usage = 0.0
        else:
            cmd = ['sh', '-c', "LC_ALL=C top -bn1 | grep 'Cpu' | head -n 1"]
            try:
                output = subprocess.check_output(cmd, stderr=subprocess.DEVNULL).decode(errors='ignore')
            except Exception:
                cpu_usage = 0.0
            else:
                line = output.strip()
                if not line:
                    cpu_usage = 0.0
                else:
                    try:
                        if 'id' in line:
                            tokens = line.replace(',', ' ').split()
                            idle = None
                            for i, t in enumerate(tokens):
                                if t.lower().startswith('id'):
                                    if i > 0:
                                        idle = float(tokens[i - 1])
                                    break
                            if idle is None:
                                cpu_usage = 0.0
                            else:
                                cpu_usage = 100.0 - idle
                        else:
                            digits = []
                            for t in line.replace(',', ' ').split():
                                try:
                                    digits.append(float(t))
                                except ValueError:
                                    pass
                            cpu_usage = digits[0] if digits else 0.0
                    except Exception:
                        cpu_usage = 0.0
        records.append({"timestamp": now, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w', encoding='utf-8') as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH

