import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    if not isinstance(script_path, str) or not isinstance(temp_dir, str):
        raise TypeError("script_path and temp_dir must be strings")
    if not os.path.isfile(script_path) or not os.path.isdir(temp_dir):
        return "Script execution failed!"
    script_name = os.path.basename(script_path)
    work_dir = os.path.join(temp_dir, "exec_temp")
    try:
        if os.path.exists(work_dir):
            shutil.rmtree(work_dir)
        os.makedirs(work_dir)
        copied_script = shutil.copy(script_path, os.path.join(work_dir, script_name))
        try:
            subprocess.run(["python", copied_script], cwd=work_dir, check=True)
        except Exception:
            return "Script execution failed!"
        return "Script executed successfully!"
    except Exception:
        return "Script execution failed!"
    finally:
        if os.path.exists(work_dir):
            shutil.rmtree(work_dir, ignore_errors=True)

