import subprocess
import os
import threading
import sys
def task_func(script_path: str, timeout: int = 60) -> str:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"{script_path} does not exist")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError("timeout must be a positive number")
    cmd = [sys.executable, script_path]
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    timeout_happened = {"flag": False}
    def kill_proc():
        if proc.poll() is None:
            timeout_happened["flag"] = True
            proc.terminate()
    timer = threading.Timer(timeout, kill_proc)
    timer.start()
    try:
        proc.communicate()
    finally:
        timer.cancel()
    if timeout_happened["flag"]:
        return "Terminating process due to timeout."
    return "Script executed successfully."

