import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    if not isinstance(r_script_path, str) or not isinstance(output_path, str) or not isinstance(duration, int):
        raise TypeError("Invalid argument types")
    if not r_script_path or not os.path.isfile(r_script_path):
        raise OSError("Invalid R script path")
    try:
        process = subprocess.Popen(["Rscript", r_script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except Exception:
        return False, "File not generated within the specified duration."
    start_time = time.time()
    success = False
    while time.time() - start_time < duration:
        matches = glob.glob(output_path)
        if matches:
            success = True
            break
        time.sleep(0.5)
    if not success:
        matches = glob.glob(output_path)
        if matches:
            success = True
