    if found:
        return True, 'File generated successfully within the specified duration.'
    else:
        return False, 'File not generated within the specified duration.'

import subprocess
import os
import threading
import sys
def task_func(script_path: str, timeout: int = 60) -> str:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.isfile(script_path):
        raise FileNotFoundError(f"No such file: {script_path}")
    process = subprocess.Popen([sys.executable, script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    def run_proc():
        process.communicate()
    t = threading.Thread(target=run_proc)
    t.start()
    t.join(timeout)
    if t.is_alive():
        try:
            process.terminate()
        except Exception:
            pass
        return "Terminating process due to timeout."
    return "Script executed successfully."

