import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError(f"{commands_file_path} does not exist")
    os.makedirs(output_dir_path, exist_ok=True)
    output_files = []
    with open(commands_file_path, newline='', encoding='utf-8') as csvfile:
        reader = csv.reader(csvfile)
        index = 1
        for row in reader:
            if not row:
                continue
            if len(row) == 1:
                cmd_str = row[0].strip()
                if not cmd_str:
                    continue
                cmd = cmd_str.split()
            else:
                cmd = [field for field in row if field is not None and field != '']
                if not cmd:
                    continue
            output_file_path = os.path.join(output_dir_path, f"command_{index}_output.txt")
            try:
                result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                if result.returncode == 0:
                    content = result.stdout
                else:
                    content = f"Command failed with exit code {result.returncode}\n"
                    if result.stderr:
                        content += result.stderr
            except Exception as e:
                content = f"Command execution error: {e}\n"
                content += "Exit code: -1\n"
            with open(output_file_path, 'w', encoding='utf-8') as f:
                f.write(content)
            output_files.append(output_file_path)
            index += 1
    return output_files

