import time
import threading
def task_func(file_list):
    processes = []
    for f in file_list:
        try:
            p = subprocess.Popen(f)
            processes.append(p)
        except Exception:
            processes.append(None)
    results = [None] * len(processes)
    def worker(proc, idx):
        if proc is None:
            results[idx] = -1
        else:
            code = proc.wait()
            results[idx] = code
    threads = []
    for idx, proc in enumerate(processes):
        t = threading.Thread(target=worker, args=(proc, idx))
        t.start()
        threads.append(t)
    for t in threads:
        t.join()
    return results

