from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not isinstance(src_folder, str) or not isinstance(dst_folder, str) or not src_folder or not dst_folder:
        return {
            'success': False,
            'message': 'Invalid source or destination folder.',
            'failed_files': []
        }
    src_folder = os.path.abspath(src_folder)
    dst_folder = os.path.abspath(dst_folder)
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': 'Source folder does not exist or is not a directory.',
            'failed_files': []
        }
    try:
        os.makedirs(dst_folder, exist_ok=True)
    except Exception:
        return {
            'success': False,
            'message': 'Failed to create destination folder.',
            'failed_files': []
        }
    pattern = os.path.join(src_folder, '*')
    files = [f for f in glob(pattern) if os.path.isfile(f)]
    if not files:
        return {
            'success': True,
            'message': 'No files to compress in the source folder.',
            'failed_files': []
        }
    for src_path in files:
        basename = os.path.basename(src_path)
        dst_path = os.path.join(dst_folder, basename + '.gz')
        try:
            with open(dst_path, 'wb') as out_f:
                proc = subprocess.Popen(['gzip', '-c', src_path], stdout=out_f, stderr=subprocess.PIPE)
                _, err = proc.communicate()
                if proc.returncode != 0:
                    failed_files.append(basename)
                    try:
                        os.remove(dst_path)
                    except Exception:
                        pass
        except Exception:
            failed_files.append(basename)
            try:
                if os.path.exists(dst_path):
                    os.remove(dst_path)
            except Exception:
                pass
    if failed_files:
        message = f'Compression completed with failures for {len(failed_files)} file(s).'
        success = False
    else:
        message = 'All files compressed and moved successfully.'
        success = True
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

