import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script_path")
    proc = subprocess.Popen(["bash", script_path])
    p = psutil.Process(proc.pid)
    cpu_usage_total = 0.0
    mem_usage_total = 0
    start_time = time.time()
    first = True
    while True:
        if time.time() - start_time > timeout:
            break
        if proc.poll() is not None:
            break
        try:
            if first:
                p.cpu_percent(interval=None)
                first = False
            time.sleep(0.1)
            cpu_usage_total += p.cpu_percent(interval=None)
            mem_info = p.memory_info()
            mem_usage_total += mem_info.rss
            if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    if proc.poll() is None:
        try:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except subprocess.TimeoutExpired:
                proc.kill()
        except Exception:
            pass
    else:
        try:
            proc.wait(timeout=1)
        except Exception:
            pass
    return {"CPU Usage": cpu_usage_total, "Memory Usage": mem_usage_total}

