import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path):
        raise OSError("Script path does not exist")
    proc = subprocess.Popen(['/bin/bash', script_path])
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    try:
        p.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        proc.poll()
        return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
    while True:
        if proc.poll() is not None:
            break
        if time.time() - start_time > timeout:
            try:
                proc.terminate()
            except Exception:
                pass
            try:
                proc.kill()
            except Exception:
                pass
            break
        try:
            cpu_inc = p.cpu_percent(interval=0.1)
            cpu_usage += cpu_inc
            if p.is_running() and p.status() != psutil.STATUS_ZOMBIE:
                mem_info = p.memory_info()
                mem_usage += mem_info.rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    try:
        proc.wait(timeout=0)
    except Exception:
        try:
            proc.kill()
        except Exception:
            pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

