import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path or not os.path.isfile(script_path):
        raise OSError("Invalid script path")
    start_time = time.time()
    proc = subprocess.Popen(["bash", script_path])
    p = psutil.Process(proc.pid)
    accumulated_cpu = 0.0
    accumulated_mem = 0
    interval = 0.1
    try:
        p.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        proc.wait(timeout=timeout)
        return {"CPU Usage": accumulated_cpu, "Memory Usage": accumulated_mem}
    while True:
        if time.time() - start_time >= timeout:
            break
        time.sleep(interval)
        try:
            cpu = p.cpu_percent(interval=None)
            mem_info = p.memory_info()
            accumulated_cpu += cpu
            accumulated_mem += mem_info.rss
            if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break
    if proc.poll() is None:
        try:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
        except Exception:
            try:
                proc.kill()
                proc.wait()
            except Exception:
                pass
    else:
        try:
            proc.wait()
        except Exception:
            pass
    return {"CPU Usage": accumulated_cpu, "Memory Usage": accumulated_mem}

