import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not script_path:
        raise FileNotFoundError("Empty script path")
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    start_time = time.time()
    process = subprocess.Popen(["bash", script_path])
    try:
        ps_proc = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {"CPU Usage": 0.0, "Memory Usage": 0}
    cpu_usage_accum = 0.0
    mem_usage_accum = 0
    last_rss = {}
    try:
        ps_proc.cpu_percent(interval=None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        return {"CPU Usage": 0.0, "Memory Usage": 0}
    interval = 0.1
    while True:
        if process.poll() is not None:
            break
        elapsed = time.time() - start_time
        if elapsed >= timeout:
            break
        time.sleep(interval)
        try:
            procs = [ps_proc] + ps_proc.children(recursive=True)
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            procs = []
        for p in procs:
            try:
                cpu = p.cpu_percent(interval=None)
                cpu_usage_accum += cpu
                mem_info = p.memory_info()
                rss = mem_info.rss
                pid = p.pid
                prev = last_rss.get(pid, 0)
                if rss > prev:
                    mem_usage_accum += rss - prev
                last_rss[pid] = rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                continue
    if process.poll() is None:
        try:
            process.terminate()
            try:
                process.wait(timeout=2)
            except subprocess.TimeoutExpired:
                process.kill()
        except Exception:
            pass
    return {"CPU Usage": cpu_usage_accum, "Memory Usage": mem_usage_accum}

